assert.deepStrictEqual(calendar.get('2'), { id: '2', start: 90, end: 120 });
assert.strictEqual(calendar.get('3'), null);

// Test list method
assert.deepStrictEqual(calendar.list(), [
  { id: '1', start: 30, end: 60 },
  { id: '2', start: 90, end: 120 }
]);

