        let total = 0;
        const items = cart.querySelectorAll('li');
        items.forEach(item => {
            const price = parseInt(item.querySelector('span').textContent.split(' ')[1]);
            total += price;
        });
        totalDisplay.textContent = `$${(total / 100).toFixed(2)}`;
    }
