            const li = event.target.parentElement;
            let quantity = parseInt(li.querySelector('span').textContent.split(' ')[1]);
            quantity--;
            if (quantity <= 0) {
                cart.removeChild(li);
            } else {
                li.querySelector('span').textContent = `${li.querySelector('span').textContent.split(' ')[0]} - ${quantity} cents`;
