    this.meetings = [];
  }

  add(id, start, end) {
    if (typeof id !== 'string' || typeof start !== 'number' || typeof end !== 'number') {
      throw new Error('Invalid input types');
    }
    if (start < 0 || start >= 1440 || end <= start || end > 1440) {
      throw new Error('Invalid start or end time');
    }
