def where(rows, column, op, value):
    def compare(row_value, value):
        if op in ('<', '>', '<=', '>='):
            try:
                row_value = float(row_value)
                value = float(value)
            except ValueError:
                pass
        if op == '=':
            return row_value == value
        elif op == '!=':
            return row_value != value
        elif op == '<':
            return row_value < value
        elif op == '>':
            return row_value > value
        elif op == '<=':
            return row_value <= value
        elif op == '>=':
            return row_value >= value
        else:
            raise ValueError(f"Unknown operator: {op}")

    filtered_rows = []
    for row in rows:
        if compare(row.get(column), value):
            filtered_rows.append(row)
