        keys = set(a.keys()).union(b.keys())
        for key in keys:
            result.extend(diff(a.get(key), b.get(key), f"{path}.{key}" if path else key))
        return result
    elif isinstance(a, list) and isinstance(b, list):
        result = []
        for i in range(max(len(a), len(b))):
            result.extend(diff(a[i] if i < len(a) else None, b[i] if i < len(b) else None, f"{path}[{i}]"))
        return result
    else:
        if a != b:
            return [(path, a, b)]
        return []
