    assert convert(1, 'kg', 'g') == 1000
    assert convert(1, 'oz', 'g') == 28.349523125
    assert convert(1, 'lb', 'g') == 453.59237
    assert convert(16, 'oz', 'lb') == 1
    assert convert(1, 'lb', 'oz') == 16
