  }

  list() {
    return this.meetings.slice().sort((a, b) => {
      if (a.start === b.start) {
        return a.id.localeCompare(b.id);
      }
      return a.start - b.start;
    });
  }

  move(id, newStart) {
    const meeting = this.meetings.find(meeting => meeting.id === id);
    if (!meeting) {
