    elif abs(qty - round(qty * 2) / 2) < 0.01:
        return f"{int(round(qty * 2) / 2)} 1/2 {unit}"
    elif abs(qty - round(qty * 3) / 3) < 0.01:
        return f"{int(round(qty * 3) / 3)} 1/3 {unit}"
    elif abs(qty - round(qty * 4) / 4) < 0.01:
        return f"{int(round(qty * 4) / 4)} 1/4 {unit}"
    else:
