class Warehouse {
  constructor() {
    this.items = {};
  }

  addItem(sku, qty) {
    if (!Number.isInteger(qty) || qty <= 0) {
      throw new Error('Quantity must be a positive integer');
    }
    if (!this.items[sku]) {
      this.items[sku] = 0;
    }
    this.items[sku] += qty;
  }

  stock(sku) {
    return this.items[sku] || 0;
  }

  skus() {
    return Object.keys(this.items).sort();
  }
}

