  }

  insert(pos, str) {
    if (pos < 0 || pos > this.text.length) {
      throw new Error('Position out of bounds');
    }
    this.text = this.text.slice(0, pos) + str + this.text.slice(pos);
    this.history.push(this.text);
    if (this.history.length > this.maxUndo) {
      this.history.shift();
    }
    this.redoStack = [];
