            try:
                row_value = float(row_value)
                value = float(value)
            except ValueError:
                pass
        if op == '=':
            return row_value == value
        elif op == '!=':
            return row_value != value
        elif op == '<':
            return row_value < value
        elif op == '>':
            return row_value > value
        elif op == '<=':
            return row_value <= value
        elif op == '>=':
            return row_value >= value
        else:
            raise ValueError(f"Unknown operator: {op}")

