            # Convert mass to grams
            converted_qty = convert(qty, unit, 'g')
        elif unit in ['l', 'ml', 'cup', 'tablespoon', 'teaspoon']:
            # Convert volume to milliliters
            converted_qty = convert(qty, unit, 'ml')
        else:
